        console.log("Owner ETH balance:", finalOwnerBalance);
        console.log("Attacker ETH balance:", finalAttackerBalance);

        // Differential Comparison
        console.log("--- Differential Verification ---");
        uint256 contractBalanceChange = initialContractBalance - finalContractBalance;
        uint256 ownerBalanceChange = finalOwnerBalance - initialOwnerBalance;
        uint256 attackerBalanceChange = finalAttackerBalance - initialAttackerBalance;

        console.log("Contract ETH change:", contractBalanceChange);
        console.log("Owner ETH change:", ownerBalanceChange);
        console.log("Attacker ETH change:", attackerBalanceChange);

        // Vulnerability condition verification
        bool fundsTransferred = contractBalanceChange == initialContractBalance && 
                               contractBalanceChange > 0;
        bool ownerGainedFunds = ownerBalanceChange == (initialContractBalance + ATTACK_AMOUNT);
        bool attackerLostFunds = attackerBalanceChange == -int256(ATTACK_AMOUNT); // Negative change

        if (fundsTransferred && ownerGainedFunds && attackerLostFunds) {
            console.log("Vulnerability Exists: ETH fully drained from contract to owner");
        } else {
            console.log("Vulnerability not Exist: ETH not drained according to expected pattern");
